  const taskIds: ImagePostWorkflow['taskIds'] = {
    ...(typeof rawTaskIds.generate === 'string' && rawTaskIds.generate ? { generate: rawTaskIds.generate } : {}),
    ...(typeof rawTaskIds.publish === 'string' && rawTaskIds.publish ? { publish: rawTaskIds.publish } : {}),
