  const receipt = rawReceipt
    ? {
        ...(typeof rawReceipt.url === 'string' && rawReceipt.url ? { url: rawReceipt.url } : {}),
        ...(typeof rawReceipt.evidence === 'string' && rawReceipt.evidence ? { evidence: rawReceipt.evidence } : {}),
