const fs=require("fs");
const p=".auto-dev/verification.md";
let s=fs.readFileSync(p,"utf8");
const frag=fs.readFileSync(".auto-dev/_vfrag.md","utf8");
const nl = /\r\n/.test(s) ? "\r\n" : "\n";
const body = /\r\n/.test(s) ? frag.replace(/\r?\n/g,"\r\n") : frag.replace(/\r\n/g,"\n");
fs.writeFileSync(p, s.replace(/\s*$/,"") + nl + nl + body);
fs.unlinkSync(".auto-dev/_vfrag.md");
console.log("appended, CRLF=", /\r\n/.test(s));
' && tail -5 .auto-dev/verification.md

